      <rect x="94" y="179" width="18" height="42" rx="9" fill="${art.accent}"/>
      <rect x="288" y="179" width="18" height="42" rx="9" fill="${art.accent}"/>
      <path d="M294 231 C302 244 301 257 294 266" fill="none" stroke="#2b2148" stroke-width="3"/>
      <circle cx="293" cy="269" r="4" fill="${art.accent2 || '#fff'}"/>`;
  }
  if (a === 'hoops') {
    return `
      <circle cx="126" cy="221" r="13" fill="none" stroke="${art.accent2}" stroke-width="3"/>
      <circle cx="274" cy="221" r="13" fill="none" stroke="${art.accent2}" stroke-width="3"/>
      <path d="M200 313 L188 329 L200 338 L212 329Z" fill="${art.accent2}" opacity=".92"/>
      <path d="M200 313 L188 329 L200 338 L212 329Z" fill="none" stroke="#2b1520" stroke-width="1" opacity=".5"/>`;
  }
  if (a === 'glasses') {
    return `
      <rect x="141" y="176" width="49" height="35" rx="13" fill="none" stroke="#d9c58f" stroke-width="2.2"/>
      <rect x="210" y="176" width="49" height="35" rx="13" fill="none" stroke="#d9c58f" stroke-width="2.2"/>
      <path d="M190 190 Q200 185 210 190" fill="none" stroke="#d9c58f" stroke-width="2"/>
      <path d="M141 185 L124 179 M259 185 L276 179" fill="none" stroke="#d9c58f" stroke-width="2"/>
      <path d="M147 182 L161 205" stroke="#fff" stroke-width="1.2" opacity=".45"/>`;
  }
  if (a === 'headband') {
    return `
      <path d="M109 153 C118 100 153 72 200 72 C247 72 282 100 291 153" fill="none" stroke="${art.accent2}" stroke-width="9" stroke-linecap="round"/>
      <path d="M112 149 C122 102 154 78 200 78 C246 78 278 102 288 149" fill="none" stroke="${mix(art.accent2, '#ffffff', 0.35)}" stroke-width="2.5" opacity=".8"/>
      <path d="M281 130 L292 119" stroke="${art.accent}" stroke-width="4" stroke-linecap="round"/>
      <circle cx="294" cy="116" r="4" fill="${art.accent}"/>`;
  }
  if (a === 'crescent') {
    return `
      <path d="M53 111 C42 96 48 76 66 68 C56 84 57 98 69 107 C64 114 58 114 53 111Z" fill="${art.accent2}" opacity=".95"/>
      ${sparkle(74, 92, 5, '#fff', 0.8)}
      <path d="M200 313 L188 329 L200 338 L212 329Z" fill="${art.accent}" opacity=".9"/>
      <circle cx="200" cy="326" r="2.2" fill="#24122b"/>`;
  }
  if (a === 'bandana') {
    return `
      <path d="M113 145 C120 93 154 67 200 67 C246 67 280 93 287 145 C257 130 230 123 200 123 C170 123 143 130 113 145Z" fill="${art.accent}"/>
      <path d="M113 145 C143 131 170 125 200 125 C230 125 257 131 287 145" fill="none" stroke="${art.accent2}" stroke-width="3" opacity=".85"/>
      <g fill="#fff" opacity=".55">
        <circle cx="150" cy="104" r="2.4"/><circle cx="174" cy="88" r="1.8"/><circle cx="203" cy="81" r="2.2"/>
        <circle cx="229" cy="90" r="1.7"/><circle cx="251" cy="108" r="2.4"/><circle cx="267" cy="128" r="1.5"/>
        <circle cx="134" cy="130" r="1.5"/><circle cx="187" cy="108" r="1.3"/><circle cx="219" cy="105" r="1.6"/>
      </g>
      <path d="M111 143 C96 138 86 146 81 159 C94 158 103 163 108 173" fill="${art.accent}"/>
      <path d="M86 157 C78 161 75 168 76 177 C84 172 92 172 99 176" fill="${art.accent}"/>
      <circle cx="112" cy="145" r="7" fill="${art.accent2}" opacity=".9"/>`;
  }
  if (a === 'pins') {
    return `
      <path d="M130 120 C140 105 155 96 172 92" fill="none" stroke="${art.hairStreak || art.accent}" stroke-width="10" stroke-linecap="round" opacity=".9"/>
      ${heart(274, 126, 10, art.accent2 || '#ff5580', -15)}
      ${sparkle(255, 105, 6, '#e9fbff', 0.9)}
      <circle cx="128" cy="226" r="4" fill="#cfd9df"/><circle cx="128" cy="238" r="3" fill="#cfd9df"/>`;
  }
  if (a === 'beanie') {
    return `
      <path d="M107 145 C107 86 148 57 200 57 C252 57 293 86 293 145Z" fill="${mix(art.accent, '#5a352f', 0.25)}"/>
      <path d="M154 143 C151 102 169 76 200 73 C231 76 249 102 246 143" fill="none" stroke="${mix(art.accent, '#ffffff', 0.15)}" stroke-width="2" opacity=".38"/>
      <rect x="101" y="133" width="198" height="35" rx="16" fill="${mix(art.accent, '#4e2f28', 0.18)}"/>
      <path d="M108 147 C148 140 252 140 292 147 M107 158 C150 151 250 151 293 158" fill="none" stroke="${mix(art.accent, '#ffffff', 0.2)}" stroke-width="2" opacity=".55"/>
      <circle cx="200" cy="56" r="7" fill="${art.accent2 || '#f4d28c'}"/>`;
  }
  if (a === 'halo') {
    return `
      <ellipse cx="200" cy="40" rx="55" ry="10" fill="none" stroke="${art.accent2 || '#f9e6ff'}" stroke-width="4" opacity=".95"/>
      <ellipse cx="200" cy="40" rx="55" ry="10" fill="none" stroke="#fff" stroke-width="1" opacity=".55"/>
      ${sparkle(139, 53, 6, '#fff', 0.7)}
      ${sparkle(267, 55, 4, '#fff', 0.55)}
      ${heart(278, 128, 9, art.accent2 || '#ff8bc6', 12)}
      <path d="M200 313 L188 329 L200 338 L212 329Z" fill="${art.accent2 || '#fff'}" opacity=".9"/>`;
  }
  return '';
}

function choker(art) {
  const color = art.outfitStyle === 'hoodie' ? art.accent : '#201320';
  return `
    <path d="M179 312 Q200 321 221 312" fill="none" stroke="${color}" stroke-width="7" stroke-linecap="round"/>
    <path d="M179 312 Q200 321 221 312" fill="none" stroke="${mix(color, '#ffffff', 0.25)}" stroke-width="1.5" stroke-linecap="round" opacity=".55"/>
    ${art.outfitStyle === 'dress' || art.outfitStyle === 'stage' ? `<circle cx="200" cy="322" r="3.2" fill="${art.accent2 || '#fff'}"/>` : ''}
  `;
}

export function portraitSVG(c) {
  const art = { ...c.art, _u: `pt-${c.id}` };
  const u = art._u;
  const hairLight = mix(art.hair, '#ffffff', 0.2);
  const hairMid = art.hair;

  return `<svg class="portrait-svg" viewBox="0 0 400 520" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Stylized portrait of ${c.name}">
    <defs>
      <linearGradient id="${u}-bg" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="${art.bg1}"/>
        <stop offset=".58" stop-color="${mix(art.bg1, art.bg2, 0.55)}"/>
        <stop offset="1" stop-color="${art.bg2}"/>
      </linearGradient>
      <radialGradient id="${u}-halo" cx=".5" cy=".42" r=".55">
        <stop offset="0" stop-color="#fff" stop-opacity=".62"/>
        <stop offset=".55" stop-color="#fff" stop-opacity=".12"/>
        <stop offset="1" stop-color="#fff" stop-opacity="0"/>
      </radialGradient>
      <linearGradient id="${u}-hair" x1=".2" y1="0" x2=".8" y2="1">
        <stop offset="0" stop-color="${hairLight}"/>
        <stop offset=".32" stop-color="${hairMid}"/>
        <stop offset="1" stop-color="${art.hairDark}"/>
      </linearGradient>
      <linearGradient id="${u}-outfit" x1=".2" y1="0" x2=".8" y2="1">
        <stop offset="0" stop-color="${mix(art.outfit, '#ffffff', 0.12)}"/>
        <stop offset=".6" stop-color="${art.outfit}"/>
        <stop offset="1" stop-color="${art.outfitDark}"/>
      </linearGradient>
    </defs>
    ${backdrop(art, u)}
    ${hairBack(art)}
    ${neck(art)}
    ${ears(art)}
    ${face(art)}
    ${body(art, c, u)}
    ${choker(art)}
    ${features(art)}
    ${hairFront(art)}
    ${accessory(art)}
  </svg>`;
}

/* ==================================================================
   CRAVE — visual system
=================================================================== */

@font-face {
  font-family: 'Instrument Serif';
  src: url('../assets/fonts/instrument-serif.woff2') format('woff2');
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Instrument Serif';
  src: url('../assets/fonts/instrument-serif-italic.woff2') format('woff2');
  font-style: italic;
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('../assets/fonts/manrope-variable.woff2') format('woff2');
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
}
@font-face {
  font-family: 'Space Mono';
  src: url('../assets/fonts/space-mono.woff2') format('woff2');
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

:root {
  --bg: #0c080d;
  --bg-soft: #140d15;
  --panel: rgba(27, 17, 28, 0.78);
  --panel-solid: #18101a;
  --ink: #fff7f0;
  --ink-soft: #e8d8dc;
  --muted: #b7a1aa;
  --muted-dim: #7f6c77;
  --line: rgba(255, 246, 241, 0.13);
  --line-soft: rgba(255, 246, 241, 0.07);
  --rose: #ff5f8f;
  --rose-deep: #e12967;
  --peach: #ffb087;
  --acid: #d8ff86;
  --danger: #ff6b6b;
  --glass: blur(20px) saturate(120%);
  --display: 'Instrument Serif', Georgia, 'Times New Roman', serif;
  --sans: 'Manrope', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --mono: 'Space Mono', 'Courier New', monospace;
  --ease: cubic-bezier(0.22, 0.68, 0.24, 1);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  color-scheme: dark;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100svh;
  overflow-x: hidden;
  background:
    radial-gradient(ellipse 70% 55% at 75% -10%, rgba(117, 37, 75, 0.35), transparent 65%),
    radial-gradient(ellipse 55% 50% at -10% 70%, rgba(68, 27, 93, 0.28), transparent 65%),
    var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input {
  font: inherit;
}

button {
  color: inherit;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

h1,
h2,
h3,
p,
blockquote {
  margin: 0;
}

::selection {
  background: var(--rose);
  color: #1a0810;
}

:focus-visible {
  outline: 2px solid var(--acid);
  outline-offset: 4px;
}

[hidden] {
  display: none !important;
}

.noise {
  position: fixed;
  inset: 0;
  z-index: 90;
  pointer-events: none;
  opacity: 0.07;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
}

.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.ambient-orb {
  position: absolute;
  display: block;
  border-radius: 50%;
  filter: blur(100px);
  opacity: 0.23;
  animation: drift 20s ease-in-out infinite alternate;
}
.orb-a {
  width: 44vw;
  height: 44vw;
  min-width: 380px;
  min-height: 380px;
  top: -21vw;
  right: -8vw;
  background: #b42d68;
}
.orb-b {
  width: 36vw;
  height: 36vw;
  min-width: 300px;
  min-height: 300px;
  left: -12vw;
  bottom: -12vw;
  background: #5d2f9d;
  animation-delay: -7s;
}
.orb-c {
  width: 22vw;
  height: 22vw;
  top: 47%;
  left: 38%;
  background: #ff8058;
  opacity: 0.08;
  animation-delay: -13s;
}
.ambient-grid {
  position: absolute;
  inset: 0;
  opacity: 0.045;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.5) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.5) 1px, transparent 1px);
  background-size: 76px 76px;
  mask-image: linear-gradient(to bottom, transparent, #000 25%, #000 70%, transparent);
}

@keyframes drift {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(5vw, 4vh, 0) scale(1.12); }
  100% { transform: translate3d(-3vw, 8vh, 0) scale(0.92); }
}

#app {
  position: relative;
  z-index: 1;
}

.screen {
  display: none;
  position: relative;
  min-height: 100svh;
  width: 100%;
}
.screen.is-active {
  display: flex;
  flex-direction: column;
  animation: screenIn 0.55s var(--ease-out) both;
}
@keyframes screenIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ==================================================================
   SHARED PIECES
=================================================================== */

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.15em;
  line-height: 1.4;
  text-transform: uppercase;
  color: var(--muted);
}
.eyebrow-mark {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--rose);
  box-shadow: 0 0 0 4px rgba(255, 95, 143, 0.12), 0 0 18px rgba(255, 95, 143, 0.65);
}

.button {
  appearance: none;
  border: 1px solid transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-height: 54px;
  padding: 14px 22px;
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font-weight: 700;
  font-size: 14px;
  line-height: 1.2;
  letter-spacing: -0.01em;
  cursor: pointer;
  transition: transform 0.22s var(--ease), background 0.22s, border-color 0.22s, color 0.22s, box-shadow 0.22s;
}
.button:hover {
  transform: translateY(-2px);
}
.button:active {
  transform: translateY(0) scale(0.985);
}
.button.primary {
  background: var(--ink);
  color: #160b11;
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.24);
}
.button.primary:hover {
  background: #fff;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.35);
}
.button.ghost {
  border-color: var(--line);
  background: rgba(255, 255, 255, 0.025);
  color: var(--ink-soft);
}
.button.ghost:hover {
  border-color: rgba(255, 255, 255, 0.32);
  background: rgba(255, 255, 255, 0.07);
}

.text-button {
  appearance: none;
  border: 0;
  background: none;
  padding: 8px 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color 0.2s;
}
.text-button:hover { color: var(--ink); }

/* ==================================================================
   SELECTION
=================================================================== */

.selection {
  padding: 22px clamp(20px, 3.2vw, 54px) 18px;
  max-width: 1600px;
  margin: 0 auto;
  justify-content: flex-start;
}

.site-header {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 26px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line-soft);
  animation: riseIn 0.65s var(--ease-out) both;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--ink);
  width: fit-content;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  color: var(--rose);
  background: rgba(255, 95, 143, 0.08);
  border: 1px solid rgba(255, 95, 143, 0.32);
  box-shadow: inset 0 0 18px rgba(255, 95, 143, 0.08);
}
.brand-mark svg { width: 21px; height: 21px; }
.brand-name {
  font-weight: 800;
  font-size: 19px;
  letter-spacing: 0.18em;
}
.brand-sub {
  margin-left: 2px;
  color: var(--muted-dim);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.header-note {
  justify-self: center;
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 12px rgba(216, 255, 134, 0.8);
  animation: pulse 2.4s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.72); }
}

.header-rule {
  justify-self: end;
  display: flex;
  gap: 22px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.11em;
  color: var(--muted-dim);
  text-transform: uppercase;
}

.select-intro {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 370px;
  align-items: end;
  gap: clamp(26px, 4vw, 68px);
  padding: clamp(26px, 3.5vw, 48px) 0 clamp(24px, 3vw, 36px);
}

.intro-copy {
  animation: riseIn 0.7s 0.06s var(--ease-out) both;
}
.intro-copy h1 {
  max-width: 860px;
  margin-top: 12px;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(48px, 5.55vw, 83px);
  line-height: 0.92;
  letter-spacing: -0.035em;
  text-wrap: balance;
}
.intro-copy h1 em {
  font-style: italic;
  color: var(--rose);
  position: relative;
  white-space: nowrap;
}
.intro-copy h1 em::after {
  content: '';
  position: absolute;
  left: 3%;
  right: 1%;
  bottom: 0.01em;
  height: 0.09em;
  background: currentColor;
  opacity: 0.4;
  transform: rotate(-1.4deg);
  border-radius: 50%;
}
.intro-sub {
  max-width: 560px;
  margin-top: 18px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
}

.rules-card {
  position: relative;
  padding: 20px 22px 19px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(255, 95, 143, 0.055), rgba(255, 255, 255, 0.015) 60%),
    rgba(20, 13, 22, 0.6);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 22px 50px rgba(0, 0, 0, 0.18);
  animation: riseIn 0.7s 0.12s var(--ease-out) both;
  overflow: hidden;
}
.rules-card::after {
  content: '♥';
  position: absolute;
  right: 14px;
  bottom: -19px;
  font-family: var(--display);
  font-size: 94px;
  color: var(--rose);
  opacity: 0.06;
  transform: rotate(-8deg);
}
.rules-head {
  display: flex;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line-soft);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.16em;
  color: var(--ink-soft);
  text-transform: uppercase;
}
.rules-count { color: var(--muted-dim); }
.rules-list {
  display: grid;
  gap: 8px;
  margin: 12px 0 13px;
  padding: 0;
  list-style: none;
}
.rules-list li {
  display: flex;
  align-items: baseline;
  gap: 10px;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.4;
}
.rules-list b { color: var(--ink-soft); font-weight: 600; }
.rule-arrow {
  width: 20px;
  flex: 0 0 20px;
  font-family: var(--mono);
  font-size: 12px;
  text-align: center;
}
.rule-arrow.up { color: var(--acid); }
.rule-arrow.down { color: var(--danger); }
.rule-arrow.flat { color: var(--muted-dim); }
.rules-warning {
  padding-top: 12px;
  border-top: 1px solid var(--line-soft);
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.75;
  letter-spacing: 0.015em;
  color: var(--muted-dim);
}
.rules-warning strong { color: var(--rose); font-weight: 400; }
.rules-warning span { color: var(--ink-soft); }

.girl-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: clamp(10px, 1.1vw, 16px);
}

.girl-card {
  --accent: #ff7eb6;
  --accent2: #7ee7ff;
  appearance: none;
  position: relative;
  isolation: isolate;
  display: block;
  width: 100%;
  aspect-ratio: 0.91;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 12px;
  overflow: hidden;
  background: var(--panel-solid);
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.24);
  animation: cardIn 0.75s var(--ease-out) both;
  animation-delay: calc(0.12s + var(--i) * 0.045s);
  transition: transform 0.38s var(--ease), box-shadow 0.38s var(--ease), border-color 0.3s;
}
@keyframes cardIn {
  from { opacity: 0; transform: translateY(22px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.girl-card:hover,
.girl-card:focus-visible {
  transform: translateY(-6px);
  border-color: color-mix(in srgb, var(--accent) 75%, white 10%);
  box-shadow:
    0 26px 50px rgba(0, 0, 0, 0.4),
    0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent),
    0 0 44px color-mix(in srgb, var(--accent) 18%, transparent);
}
.girl-card:active { transform: translateY(-2px) scale(0.99); }

.card-art {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--accent);
  overflow: hidden;
}
.card-art .portrait-svg {
  width: 100%;
  height: 100%;
  display: block;
  transform: scale(1.005);
  transition: transform 0.75s var(--ease-out), filter 0.4s;
}
.girl-card:hover .card-art .portrait-svg {
  transform: scale(1.055) translateY(-1%);
  filter: saturate(1.06);
}

.card-shade {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(to bottom, rgba(12, 6, 13, 0.04) 30%, transparent 48%),
    linear-gradient(to top, rgba(8, 4, 9, 0.92) 0%, rgba(8, 4, 9, 0.54) 20%, transparent 48%);
  pointer-events: none;
}

.card-top {
  position: absolute;
  top: 11px;
  left: 12px;
  right: 12px;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: rgba(255, 255, 255, 0.72);
  text-transform: uppercase;
  text-shadow: 0 1px 7px rgba(0, 0, 0, 0.45);
}
.card-number {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.card-number::before {
  content: '';
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--accent2);
  box-shadow: 0 0 7px color-mix(in srgb, var(--accent2) 70%, transparent);
}
.card-heart {
  display: grid;
  place-items: center;
  width: 23px;
  height: 23px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.33);
  background: rgba(12, 6, 13, 0.17);
  backdrop-filter: blur(8px);
  color: #fff;
  font-size: 11px;
  line-height: 1;
  transition: background 0.3s, border-color 0.3s, transform 0.3s;
}
.girl-card:hover .card-heart {
  background: var(--accent);
  border-color: var(--accent);
  color: #13090e;
  transform: rotate(-8deg) scale(1.08);
}

.card-info {
  position: absolute;
  z-index: 2;
  left: 15px;
  right: 13px;
  bottom: 13px;
  pointer-events: none;
}
.card-kicker {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 3px;
  color: color-mix(in srgb, var(--accent2) 85%, white 15%);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  text-shadow: 0 1px 9px rgba(0, 0, 0, 0.75);
}
.card-name {
  font-family: var(--display);
  font-size: clamp(21px, 1.65vw, 27px);
  font-weight: 400;
  line-height: 0.98;
  letter-spacing: -0.02em;
  text-shadow: 0 2px 16px rgba(0, 0, 0, 0.45);
}
.card-tag {
  margin-top: 4px;
  color: rgba(255, 247, 240, 0.7);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.025em;
}
.card-cta {
  position: absolute;
  z-index: 3;
  top: 50%;
  left: 50%;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 11px;
  border: 1px solid rgba(255, 255, 255, 0.34);
  border-radius: 999px;
  background: rgba(14, 8, 15, 0.56);
  backdrop-filter: blur(14px);
  color: #fff;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  opacity: 0;
  transform: translate(-50%, -30%);
  transition: opacity 0.28s, transform 0.38s var(--ease-out);
  pointer-events: none;
  white-space: nowrap;
}
.card-cta span { color: var(--accent2); }
.girl-card:hover .card-cta,
.girl-card:focus-visible .card-cta {
  opacity: 1;
  transform: translate(-50%, -50%);
}

.select-footer {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 20px;
  align-items: center;
  margin-top: auto;
  padding: 17px 2px 0;
  color: var(--muted-dim);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.select-footer > :last-child { justify-self: end; }
.footer-center { color: var(--muted); }
.select-footer em { color: var(--ink-soft); font-style: normal; }
.tiny-heart { color: var(--rose); margin-right: 4px; }

@keyframes riseIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ==================================================================
   DATE
=================================================================== */

.date-screen {
  --accent: #ff7eb6;
  --accent2: #7ee7ff;
  padding: 16px clamp(18px, 2.6vw, 46px) 24px;
  overflow: hidden auto;
  background:
    radial-gradient(ellipse 90% 70% at 95% 0%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 65%),
    radial-gradient(ellipse 60% 70% at 3% 100%, color-mix(in srgb, var(--accent2) 7%, transparent), transparent 65%);
}

.date-atmosphere {
  position: absolute;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}
.date-word {
  position: absolute;
  top: 7%;
  left: 24%;
  font-family: var(--display);
  font-size: clamp(160px, 24vw, 360px);
  line-height: 0.7;
  letter-spacing: -0.06em;
  color: var(--accent);
  opacity: 0.035;
  transform: rotate(-5deg);
  white-space: nowrap;
}
.date-ring {
  position: absolute;
  border: 1px solid var(--accent);
  border-radius: 50%;
  opacity: 0.12;
}
.ring-one {
  width: 42vw;
  height: 42vw;
  left: -15vw;
  top: 25vh;
}
.ring-two {
  width: 63vw;
  height: 63vw;
  right: -36vw;
  bottom: -31vw;
  border-color: var(--accent2);
  opacity: 0.07;
}
.date-spark {
  position: absolute;
  color: var(--accent);
  opacity: 0.45;
  animation: twinkle 5s ease-in-out infinite;
}
.spark-a { top: 19%; right: 9%; font-size: 19px; }
.spark-b { bottom: 12%; left: 44%; font-size: 12px; animation-delay: -2s; opacity: 0.26; }
.spark-c { top: 38%; left: 3%; font-size: 8px; animation-delay: -3.3s; opacity: 0.3; }
@keyframes twinkle {
  0%, 100% { opacity: 0.2; transform: scale(0.8) rotate(0); }
  50% { opacity: 0.7; transform: scale(1.1) rotate(10deg); }
}

.game-header {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 20px;
  width: 100%;
  max-width: 1480px;
  margin: 0 auto;
  padding: 0 2px 14px;
  border-bottom: 1px solid var(--line-soft);
}
.game-brand {
  font-weight: 800;
  font-size: 13px;
  letter-spacing: 0.17em;
}
.game-brand span {
  color: var(--muted-dim);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 400;
  letter-spacing: 0.1em;
  margin-left: 5px;
}
.date-index {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: var(--muted-dim);
  text-transform: uppercase;
}
.date-progress {
  width: 88px;
  height: 3px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
}
.date-progress i {
  display: block;
  width: 14%;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
  transition: width 0.45s var(--ease);
}

.date-layout {
  display: grid;
  grid-template-columns: minmax(300px, 0.86fr) minmax(520px, 1.14fr);
  gap: clamp(22px, 3.4vw, 58px);
  width: 100%;
  max-width: 1480px;
  margin: 0 auto;
  padding-top: clamp(16px, 2.3vw, 30px);
  flex: 1;
  min-height: 0;
}

.date-character {
  display: flex;
  flex-direction: column;
  min-height: 0;
  animation: riseIn 0.65s 0.05s var(--ease-out) both;
}

.portrait-frame {
  position: relative;
  flex: 1 1 auto;
  min-height: 290px;
  border: 1px solid var(--line);
  border-radius: 20px;
  overflow: hidden;
  background: color-mix(in srgb, var(--accent) 25%, #140d15);
  box-shadow:
    0 32px 70px rgba(0, 0, 0, 0.33),
    inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}
.portrait-frame::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(to top, rgba(10, 5, 11, 0.4), transparent 35%);
}
.portrait-frame .portrait-svg {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 290px;
  object-fit: cover;
}
.portrait-label {
  position: absolute;
  top: 13px;
  left: 14px;
  z-index: 2;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.13em;
  color: rgba(255, 255, 255, 0.65);
  text-transform: uppercase;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.65);
}
.portrait-corner {
  position: absolute;
  z-index: 2;
  top: 10px;
  right: 13px;
  color: #fff;
  font-size: 15px;
  opacity: 0.5;
}

.character-caption {
  flex: 0 0 auto;
  padding: 14px 2px 8px;
}
.char-kicker {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 3px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.11em;
  color: var(--muted-dim);
  text-transform: uppercase;
}
.char-kicker span:first-child { color: var(--accent); }
.char-kicker span:last-child { margin-left: auto; color: var(--muted); }
.character-caption h2 {
  font-family: var(--display);
  font-size: clamp(36px, 3.2vw, 50px);
  font-weight: 400;
  line-height: 0.96;
  letter-spacing: -0.025em;
}
.char-tag {
  margin-top: 2px;
  color: var(--accent);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.danger-card {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 4px;
  padding: 9px 11px;
  border: 1px solid color-mix(in srgb, var(--danger) 20%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--danger) 5%, transparent);
}
.danger-icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 16px;
  height: 16px;
  margin-top: 1px;
  border: 1px solid color-mix(in srgb, var(--danger) 50%, transparent);
  border-radius: 50%;
  color: var(--danger);
  font-family: var(--mono);
  font-size: 9px;
}
.danger-card p {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.danger-card p span {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: var(--danger);
  text-transform: uppercase;
}
.danger-card p b {
  margin-top: 1px;
  color: var(--ink-soft);
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1.35;
}
.char-blurb {
  padding: 8px 2px 0;
  color: var(--muted-dim);
  font-size: 10.5px;
  line-height: 1.5;
}

.dialogue-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: clamp(18px, 2.2vw, 28px);
  border: 1px solid var(--line);
  border-radius: 24px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.045), transparent 32%),
    color-mix(in srgb, var(--panel) 88%, var(--accent) 4%);
  backdrop-filter: var(--glass);
  box-shadow:
    0 32px 80px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.055);
  animation: riseIn 0.7s 0.12s var(--ease-out) both;
}

.love-panel {
  padding-bottom: 17px;
  border-bottom: 1px solid var(--line-soft);
}
.love-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 22px;
}
.love-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.heart-icon {
  display: inline-flex;
  color: var(--rose);
  filter: drop-shadow(0 0 7px rgba(255, 95, 143, 0.34));
}
.heart-icon svg { width: 16px; height: 16px; }
.love-label strong {
  margin-left: 2px;
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.love-status {
  max-width: 330px;
  text-align: right;
}
.love-status > span {
  display: block;
  color: var(--accent);
  font-size: 12px;
  font-weight: 700;
}
.love-status small {
  display: block;
  margin-top: 1px;
  color: var(--muted-dim);
  font-size: 9.5px;
  line-height: 1.4;
}
.love-meter {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 11px;
}
.love-track {
  position: relative;
  flex: 1;
  height: 14px;
  overflow: hidden;
  border-radius: 999px;
  background:
    repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(255, 255, 255, 0.08) calc(10% - 1px) 10%),
    rgba(255, 255, 255, 0.055);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.5);
}
.love-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 40%;
  border-radius: inherit;
  background:
    linear-gradient(90deg, #ff3f79 0%, #ff7a62 45%, #ffb45e 76%, #d8ff86 100%);
  background-size: 200% 100%;
  background-position: 0 0;
  box-shadow: 0 0 18px rgba(255, 95, 143, 0.48);
  transition: width 0.7s var(--ease-out), box-shadow 0.4s;
  z-index: 1;
}
.love-shine {
  position: absolute;
  z-index: 2;
  top: 2px;
  bottom: 2px;
  width: 68px;
  left: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.48), transparent);
  opacity: 0.55;
  pointer-events: none;
  transition: left 0.7s var(--ease-out), opacity 0.3s;
}
.love-ticks {
  position: absolute;
  z-index: 3;
  inset: 0;
  display: flex;
  justify-content: space-evenly;
  pointer-events: none;
}
.love-ticks i {
  width: 1px;
  height: 100%;
  background: rgba(12, 6, 13, 0.26);
}
.meter-heart {
  position: relative;
  z-index: 4;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 50%;
  background: var(--rose);
  color: #1b080f;
  font-size: 11px;
  box-shadow: 0 0 16px rgba(255, 95, 143, 0.55);
  transition: transform 0.3s var(--ease), background 0.3s;
}
.love-delta {
  position: absolute;
  z-index: 6;
  top: -12px;
  left: 44%;
  color: var(--acid);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  opacity: 0;
  pointer-events: none;
  transform: translateY(4px);
}
.love-delta.show {
  animation: deltaFloat 1.15s var(--ease-out) both;
}
.love-delta.negative { color: var(--danger); }
@keyframes deltaFloat {
  0% { opacity: 0; transform: translateY(8px) scale(0.85); }
  18% { opacity: 1; transform: translateY(0) scale(1); }
  100% { opacity: 0; transform: translateY(-26px) scale(1.04); }
}
.love-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 5px;
  color: var(--muted-dim);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.love-scale span:nth-child(1) { color: color-mix(in srgb, var(--danger) 75%, var(--muted-dim)); }
.love-scale span:nth-child(3) { color: color-mix(in srgb, var(--acid) 65%, var(--muted-dim)); }

.conversation {
  display: flex;
  flex: 1;
  flex-direction: column;
  justify-content: center;
  min-height: 150px;
  padding: clamp(13px, 2.1vh, 24px) 0 clamp(12px, 1.8vh, 20px);
}
.speaker-row {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--muted-dim);
}
.speaker-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 7px color-mix(in srgb, var(--accent) 60%, transparent);
}
#speaker-name { color: var(--ink-soft); }
.speaker-says { color: var(--muted-dim); }
.turn-chip {
  margin-left: auto;
  padding: 3px 6px;
  border: 1px solid var(--line-soft);
  border-radius: 4px;
}
.dialogue-text {
  max-width: 720px;
  font-family: var(--display);
  font-size: clamp(25px, 2.25vw, 35px);
  line-height: 1.13;
  letter-spacing: -0.02em;
  color: var(--ink);
  text-wrap: pretty;
}
.dialogue-text::before {
  content: '“';
  color: var(--accent);
  margin-left: -0.34em;
  margin-right: 0.03em;
  opacity: 0.9;
}
.dialogue-text::after {
  content: '”';
  color: var(--accent);
  opacity: 0.5;
}

.reaction {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto;
  align-items: start;
  gap: 9px;
  margin-top: 12px;
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.035);
  animation: reactionIn 0.32s var(--ease-out) both;
}
@keyframes reactionIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}
.reaction.good {
  border-color: rgba(216, 255, 134, 0.24);
  background: rgba(216, 255, 134, 0.045);
}
.reaction.bad {
  border-color: rgba(255, 107, 107, 0.25);
  background: rgba(255, 107, 107, 0.045);
}
.reaction.neutral {
  border-color: rgba(255, 255, 255, 0.12);
}
.reaction-glyph {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.07);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 12px;
}
.reaction.good .reaction-glyph { color: var(--acid); background: rgba(216, 255, 134, 0.1); }
.reaction.bad .reaction-glyph { color: var(--danger); background: rgba(255, 107, 107, 0.1); }
.reaction p {
  color: var(--ink-soft);
  font-size: 11px;
  line-height: 1.48;
}
.reaction-effect {
  padding-top: 2px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.05em;
  white-space: nowrap;
}
.reaction.good .reaction-effect { color: var(--acid); }
.reaction.bad .reaction-effect { color: var(--danger); }

.responses {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.response-btn {
  appearance: none;
  position: relative;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 8px;
  min-height: 57px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.025);
  color: var(--ink-soft);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s, transform 0.2s var(--ease), color 0.2s;
}
.response-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent) 58%, transparent);
  background: color-mix(in srgb, var(--accent) 7%, rgba(255, 255, 255, 0.03));
  color: var(--ink);
}
.response-btn:active:not(:disabled) { transform: translateY(0) scale(0.995); }
.key {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--line-soft);
  border-radius: 5px;
  color: var(--muted-dim);
  font-family: var(--mono);
  font-size: 8px;
  transition: color 0.2s, border-color 0.2s;
}
.response-btn:hover .key {
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 45%, transparent);
}
.option-text {
  font-size: 11.5px;
  line-height: 1.4;
  letter-spacing: -0.005em;
}
.option-arrow {
  justify-self: end;
  color: var(--muted-dim);
  font-size: 13px;
  opacity: 0.4;
  transition: opacity 0.2s, transform 0.2s, color 0.2s;
}
.response-btn:hover .option-arrow {
  opacity: 1;
  color: var(--accent);
  transform: translateX(2px);
}
.responses.is-locked .response-btn {
  cursor: default;
  pointer-events: none;
}
.responses.is-locked .response-btn:not(.is-chosen) {
  opacity: 0.2;
  filter: saturate(0.4);
}
.response-btn.is-chosen {
  border-color: var(--line);
  background: rgba(255, 255, 255, 0.055);
  opacity: 1 !important;
  filter: none !important;
}
.response-btn.is-good {
  border-color: rgba(216, 255, 134, 0.34);
  background: rgba(216, 255, 134, 0.065);
}
.response-btn.is-bad {
  border-color: rgba(255, 107, 107, 0.34);
  background: rgba(255, 107, 107, 0.065);
}
.response-btn.is-neutral {
  border-color: rgba(255, 255, 255, 0.2);
}
.response-btn.is-good .key { color: var(--acid); border-color: rgba(216, 255, 134, 0.28); }
.response-btn.is-bad .key { color: var(--danger); border-color: rgba(255, 107, 107, 0.28); }

.date-hint {
  padding-top: 8px;
  color: var(--muted-dim);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.07em;
  text-align: center;
  text-transform: uppercase;
  transition: color 0.3s;
}
.date-screen.is-warm .love-fill {
  box-shadow: 0 0 26px rgba(255, 95, 143, 0.68);
}
.date-screen.is-close .love-fill {
  animation: throb 0.75s ease-in-out infinite;
}
@keyframes throb {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.35); }
}
.date-screen.is-bad .dialogue-panel {
  animation: nudge 0.35s ease-in-out;
}
@keyframes nudge {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-5px); }
  45% { transform: translateX(4px); }
  70% { transform: translateX(-2px); }
}
.date-screen.is-good .portrait-frame {
  animation: warmGlow 0.75s ease-out;
}
@keyframes warmGlow {
  0% { box-shadow: 0 32px 70px rgba(0, 0, 0, 0.33); }
  40% { box-shadow: 0 32px 70px rgba(0, 0, 0, 0.33), 0 0 60px color-mix(in srgb, var(--accent) 28%, transparent); }
  100% { box-shadow: 0 32px 70px rgba(0, 0, 0, 0.33); }
}

.floating-heart {
  position: fixed;
  z-index: 70;
  pointer-events: none;
  color: var(--rose);
  font-size: 15px;
  animation: floatHeart 1.4s var(--ease-out) both;
}
@keyframes floatHeart {
  0% { opacity: 0; transform: translate(0, 0) scale(0.5) rotate(0); }
  20% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(1.1) rotate(var(--rot)); }
}

/* ==================================================================
   BELLY
=================================================================== */

.belly-screen {
  --accent: #ff7eb6;
  --acid-level: 16%;
  --skin: #6f1d36;
  --skin-deep: #3f0c22;
  padding: 16px clamp(18px, 2.6vw, 46px) 22px;
  overflow: hidden auto;
  background:
    radial-gradient(ellipse 80% 70% at 50% 35%, #62162f 0%, #320b20 47%, #11070e 84%);
}

.belly-atmosphere {
  position: absolute;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}
.flesh-blob {
  position: absolute;
  display: block;
  border-radius: 50%;
  filter: blur(50px);
  opacity: 0.27;
  background: #8f2344;
  animation: breathe 7s ease-in-out infinite;
}
.blob-a { width: 44vw; height: 30vw; left: -10vw; top: 8vh; }
.blob-b { width: 38vw; height: 38vw; right: -15vw; bottom: -10vw; background: #b53348; animation-delay: -2.5s; }
.blob-c { width: 22vw; height: 22vw; left: 36vw; top: -14vw; background: #d35d5d; opacity: 0.12; animation-delay: -4s; }
@keyframes breathe {
  0%, 100% { transform: scale(1) translate(0, 0); }
  50% { transform: scale(1.09) translate(2vw, -2vh); }
}
.belly-grain {
  position: absolute;
  inset: 0;
  opacity: 0.16;
  mix-blend-mode: overlay;
  background-image: repeating-radial-gradient(circle at 50% 60%, transparent 0 7px, rgba(255, 255, 255, 0.035) 8px 9px);
  mask-image: radial-gradient(ellipse at center, #000, transparent 75%);
}

.belly-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  width: 100%;
  max-width: 1420px;
  margin: 0 auto;
  padding: 2px 2px 14px;
  border-bottom: 1px solid rgba(255, 220, 226, 0.12);
}
.belly-kicker { color: #f0b4c3; }
.belly-kicker .eyebrow-mark { background: var(--accent); }
.belly-header h1 {
  margin-top: 4px;
  font-family: var(--display);
  font-size: clamp(29px, 2.8vw, 43px);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.025em;
  color: #fff4ee;
}
.belly-love {
  position: relative;
  display: flex;
  align-items: baseline;
  color: #ffd6df;
  font-family: var(--display);
  font-size: clamp(42px, 4.6vw, 68px);
  line-height: 0.85;
  text-shadow: 0 0 30px rgba(255, 95, 143, 0.3);
}
.belly-love sup { font-size: 0.35em; margin-left: 2px; }
.belly-love small {
  margin-left: 8px;
  color: rgba(255, 224, 230, 0.46);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
}

.belly-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.48fr) minmax(300px, 0.72fr);
  gap: clamp(18px, 2.5vw, 38px);
  width: 100%;
  max-width: 1420px;
  margin: 0 auto;
  padding-top: clamp(16px, 2.2vw, 28px);
  flex: 1;
  min-height: 0;
}

.belly-chamber {
  position: relative;
  isolation: isolate;
  min-height: 480px;
  border: 1px solid rgba(255, 213, 220, 0.15);
  border-radius: 47% 47% 36% 36% / 16% 16% 22% 22%;
  overflow: hidden;
  background:
    radial-gradient(ellipse 65% 58% at 48% 39%, rgba(255, 155, 151, 0.42) 0%, rgba(194, 64, 80, 0.16) 36%, transparent 66%),
    radial-gradient(ellipse 75% 70% at 50% 78%, #92283f 0%, #5b132c 38%, #2d0919 72%, #15060e 100%);
  box-shadow:
    inset 0 0 95px rgba(30, 2, 12, 0.9),
    inset 0 0 28px rgba(255, 157, 160, 0.14),
    0 36px 90px rgba(0, 0, 0, 0.36);
  animation: chamberIn 0.8s var(--ease-out) both;
}
@keyframes chamberIn {
  from { opacity: 0; transform: scale(0.97); }
  to { opacity: 1; transform: scale(1); }
}
.belly-chamber::before {
  content: '';
  position: absolute;
  z-index: 0;
  inset: 5% 8% 7%;
  border-radius: 50% 50% 40% 40% / 45% 45% 30% 30%;
  background:
    radial-gradient(ellipse at 50% 34%, rgba(255, 186, 170, 0.16), transparent 48%),
    repeating-radial-gradient(ellipse at 50% 58%, transparent 0 22px, rgba(255, 147, 146, 0.035) 23px 25px);
  filter: blur(0.2px);
}
.belly-chamber::after {
  content: '';
  position: absolute;
  z-index: 5;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  box-shadow: inset 0 0 65px 16px rgba(17, 2, 9, 0.6);
}
.chamber-glow {
  position: absolute;
  z-index: 1;
  left: 50%;
  top: 40%;
  width: 55%;
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 196, 175, 0.17), transparent 68%);
  filter: blur(8px);
  animation: pulseGlow 4.5s ease-in-out infinite;
  pointer-events: none;
}
@keyframes pulseGlow {
  0%, 100% { opacity: 0.7; transform: translate(-50%, -50%) scale(0.95); }
  50% { opacity: 1; transform: translate(-50%, -50%) scale(1.08); }
}

.chamber-ridges {
  position: absolute;
  z-index: 2;
  inset: 0;
  pointer-events: none;
  opacity: 0.7;
}
.chamber-ridges span {
  position: absolute;
  display: block;
  width: 42%;
  height: 11%;
  border-radius: 50%;
  border-top: 2px solid rgba(255, 170, 168, 0.16);
  filter: blur(1px);
  transform: rotate(-20deg);
}
.chamber-ridges span:nth-child(1) { left: -12%; top: 20%; }
.chamber-ridges span:nth-child(2) { right: -13%; top: 32%; transform: rotate(22deg); }
.chamber-ridges span:nth-child(3) { left: -16%; top: 51%; transform: rotate(-13deg); }
.chamber-ridges span:nth-child(4) { right: -10%; top: 60%; transform: rotate(15deg); }
.chamber-ridges span:nth-child(5) { left: 10%; bottom: 7%; width: 80%; height: 7%; transform: rotate(3deg); border-top-color: rgba(255, 170, 168, 0.09); }

.acid {
  position: absolute;
  z-index: 3;
  left: -4%;
  right: -4%;
  bottom: -4%;
  height: var(--acid-level);
  min-height: 8%;
  border-radius: 45% 45% 0 0 / 8% 8% 0 0;
  background:
    linear-gradient(to bottom, rgba(255, 186, 122, 0.78), rgba(212, 104, 70, 0.72) 30%, rgba(132, 36, 52, 0.86)),
    radial-gradient(ellipse at 50% 0, rgba(255, 224, 153, 0.55), transparent 60%);
  box-shadow: 0 -8px 38px rgba(255, 149, 95, 0.25);
  transition: height 0.8s linear;
  pointer-events: none;
}
.acid-surface {
  position: absolute;
  top: -10px;
  left: 0;
  right: 0;
  height: 22px;
  border-radius: 50%;
  background: radial-gradient(ellipse at 50% 48%, #ffd28e 0%, #f7a468 36%, transparent 72%);
  opacity: 0.78;
  filter: blur(2px);
  animation: acidWave 4.2s ease-in-out infinite;
}
@keyframes acidWave {
  0%, 100% { transform: translateX(-1.5%) scaleY(1); }
  50% { transform: translateX(1.5%) scaleY(1.35); }
}

.chamber-hearts {
  position: absolute;
  z-index: 4;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.ambient-heart {
  position: absolute;
  bottom: -20px;
  color: rgba(255, 170, 187, 0.55);
  font-size: 12px;
  animation: heartRise 7s linear infinite;
  text-shadow: 0 0 12px rgba(255, 110, 140, 0.35);
}
@keyframes heartRise {
  0% { opacity: 0; transform: translateY(0) scale(0.6) rotate(0); }
  15% { opacity: 0.75; }
  80% { opacity: 0.3; }
  100% { opacity: 0; transform: translateY(-70vh) scale(1) rotate(20deg); }
}

.player {
  position: absolute;
  z-index: 6;
  left: 50%;
  top: 43%;
  width: clamp(76px, 8vw, 112px);
  transform: translate(-50%, -50%) translate(var(--px, 0), var(--py, 0)) rotate(var(--pr, 0deg));
  transition: transform 0.18s var(--ease-out);
  filter: drop-shadow(0 12px 22px rgba(30, 2, 10, 0.55));
  animation: bob 3.8s ease-in-out infinite;
  will-change: transform;
}
@keyframes bob {
  0%, 100% { margin-top: 0; }
  50% { margin-top: -7px; }
}
.player svg {
  display: block;
  width: 100%;
  height: auto;
  animation: playerWobble 2.8s ease-in-out infinite;
}
@keyframes playerWobble {
  0%, 100% { transform: rotate(-2deg); }
  50% { transform: rotate(2deg); }
}
.player.struggling svg {
  animation: playerStruggle 0.55s ease-in-out;
}
@keyframes playerStruggle {
  0% { transform: rotate(0) scale(1); }
  20% { transform: rotate(-13deg) scale(1.06); }
  45% { transform: rotate(12deg) scale(0.94); }
  70% { transform: rotate(-6deg) scale(1.03); }
  100% { transform: rotate(0) scale(1); }
}
.player-shadow {
  position: absolute;
  left: 50%;
  bottom: -9px;
  width: 70%;
  height: 12px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: rgba(20, 0, 8, 0.42);
  filter: blur(6px);
}
.player-tag {
  position: absolute;
  left: 50%;
  top: -15px;
  transform: translateX(-50%);
  color: rgba(255, 238, 228, 0.75);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.17em;
}
.belly-screen.is-loss .player {
  filter: drop-shadow(0 12px 22px rgba(30, 2, 10, 0.55)) saturate(0.8);
}
.belly-screen.is-loss .player svg {
  animation-duration: 0.9s;
}

.bubbles {
  position: absolute;
  z-index: 7;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.bubble {
  position: absolute;
  bottom: 15%;
  border-radius: 50%;
  border: 1px solid rgba(255, 228, 203, 0.4);
  background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.45), rgba(255, 209, 167, 0.06) 45%, transparent 70%);
  animation: bubbleUp 1.6s ease-out forwards;
}
@keyframes bubbleUp {
  0% { opacity: 0; transform: translateY(0) scale(0.5); }
  18% { opacity: 1; }
  100% { opacity: 0; transform: translateY(-170px) scale(1.15); }
}

.giggle-bubble {
  position: absolute;
  z-index: 9;
  top: 7%;
  left: 8%;
  max-width: 235px;
  padding: 10px 13px;
  border: 1px solid rgba(255, 220, 225, 0.22);
  border-radius: 14px 14px 14px 4px;
  background: rgba(58, 10, 28, 0.62);
  backdrop-filter: blur(14px);
  color: #ffe7e8;
  font-family: var(--display);
  font-size: 17px;
  line-height: 1.15;
  letter-spacing: 0.005em;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.22);
  animation: giggleIn 0.45s var(--ease-out) both;
}
.giggle-bubble::after {
  content: '';
  position: absolute;
  left: 14px;
  bottom: -6px;
  width: 12px;
  height: 12px;
  background: inherit;
  border-right: 1px solid rgba(255, 220, 225, 0.22);
  border-bottom: 1px solid rgba(255, 220, 225, 0.22);
  transform: rotate(45deg);
}
@keyframes giggleIn {
  from { opacity: 0; transform: translateY(-5px) scale(0.94); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.chamber-caption {
  position: absolute;
  z-index: 8;
  left: 50%;
  bottom: 13px;
  display: flex;
  gap: 14px;
  transform: translateX(-50%);
  white-space: nowrap;
  color: rgba(255, 224, 228, 0.43);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.13em;
}
.chamber-caption span:first-child { color: rgba(255, 228, 232, 0.72); }
.chamber-caption span:first-child::before {
  content: '';
  display: inline-block;
  width: 5px;
  height: 5px;
  margin-right: 5px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 7px rgba(216, 255, 134, 0.65);
}
.belly-screen.is-loss .chamber-caption span:first-child::before { background: var(--danger); box-shadow: 0 0 7px rgba(255, 107, 107, 0.65); }

.belly-side {
  display: flex;
  flex-direction: column;
  min-height: 0;
  animation: riseIn 0.7s 0.1s var(--ease-out) both;
}
.belly-girl-wrap {
  position: relative;
  flex: 0 0 auto;
  width: min(100%, 250px);
  aspect-ratio: 1;
  margin-bottom: 13px;
}
.belly-girl {
  position: absolute;
  inset: 6px;
  overflow: hidden;
  border: 1px solid rgba(255, 225, 228, 0.2);
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.25);
}
.belly-girl .portrait-svg {
  width: 100%;
  height: 100%;
  transform: scale(1.2) translateY(2%);
}
.belly-girl-ring {
  position: absolute;
  inset: -2px;
  border: 1px dashed rgba(255, 220, 225, 0.22);
  border-radius: 50%;
  animation: spin 40s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
.belly-girl-label {
  position: absolute;
  left: 50%;
  bottom: 9px;
  transform: translateX(-50%);
  padding: 3px 7px;
  border-radius: 999px;
  background: rgba(30, 5, 15, 0.72);
  color: rgba(255, 232, 234, 0.77);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.11em;
  white-space: nowrap;
}
.belly-quote {
  font-family: var(--display);
  font-size: clamp(19px, 1.65vw, 25px);
  line-height: 1.17;
  letter-spacing: -0.01em;
  color: #ffebe5;
  text-wrap: pretty;
}
.belly-quote::before { content: '“'; color: var(--accent); }
.belly-quote::after { content: '”'; color: var(--accent); }

.belly-status {
  display: grid;
  gap: 0;
  margin: 15px 0;
  border-top: 1px solid rgba(255, 220, 226, 0.13);
  border-bottom: 1px solid rgba(255, 220, 226, 0.13);
}
.status-row {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 220, 226, 0.07);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.1em;
}
.status-row:last-child { border-bottom: 0; }
.status-row span { color: rgba(255, 222, 228, 0.42); }
.status-row strong { color: #ffdbe1; font-weight: 400; text-align: right; }
.belly-screen.is-loss .status-row strong { color: #ffc0c0; }

.belly-actions {
  display: grid;
  gap: 8px;
  margin-top: auto;
}
.struggle-button {
  justify-content: flex-start;
  min-height: 58px;
  padding: 10px 19px;
  border-radius: 12px;
  background: linear-gradient(100deg, #ffd4dd, #ffece3);
  color: #2d0b17;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.22), 0 0 30px rgba(255, 153, 175, 0.08);
}
.struggle-button:hover {
  background: #fff5ef;
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.3), 0 0 32px rgba(255, 153, 175, 0.16);
}
.button-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: #2d0b17;
  color: #ffd8df;
  font-size: 16px;
}
.struggle-button > span:last-child {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1.2;
}
.struggle-button b { font-size: 13px; font-weight: 700; }
.struggle-button small { margin-top: 2px; font-size: 9px; font-weight: 500; opacity: 0.55; }
.leave-button {
  border-radius: 12px;
  min-height: 46px;
  font-size: 11px;
}
.belly-hint {
  margin-top: 10px;
  color: rgba(255, 223, 229, 0.4);
  font-family: var(--mono);
  font-size: 7.5px;
  line-height: 1.6;
  letter-spacing: 0.05em;
  text-align: center;
}

/* ==================================================================
   DEATH
=================================================================== */

.death-screen {
  align-items: center;
  justify-content: center;
  padding: 40px 22px;
  text-align: center;
  background:
    radial-gradient(ellipse 60% 60% at 50% 44%, rgba(122, 20, 35, 0.33), transparent 70%),
    #090508;
}
.death-halo {
  position: absolute;
  left: 50%;
  top: 44%;
  width: min(78vw, 790px);
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(255, 107, 107, 0.12);
  border-radius: 50%;
  box-shadow: 0 0 150px rgba(123, 15, 34, 0.2), inset 0 0 120px rgba(123, 15, 34, 0.11);
  pointer-events: none;
}
.death-halo::before,
.death-halo::after {
  content: '';
  position: absolute;
  border: 1px dashed rgba(255, 107, 107, 0.11);
  border-radius: 50%;
}
.death-halo::before { inset: 12%; }
.death-halo::after { inset: 30%; }
.death-inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 720px;
  animation: deathIn 1s var(--ease-out) both;
}
@keyframes deathIn {
  from { opacity: 0; transform: translateY(13px); filter: blur(8px); }
  to { opacity: 1; transform: translateY(0); filter: blur(0); }
}
.death-inner .eyebrow { color: rgba(255, 179, 179, 0.56); }
.death-inner .eyebrow-mark { background: var(--danger); box-shadow: 0 0 16px rgba(255, 107, 107, 0.5); }
.death-inner h1 {
  margin-top: 18px;
  font-family: var(--display);
  font-size: clamp(88px, 15vw, 196px);
  font-weight: 400;
  line-height: 0.78;
  letter-spacing: -0.055em;
  color: #ffd9d5;
  text-shadow: 0 0 70px rgba(255, 72, 92, 0.2);
}
.death-sub {
  margin-top: 13px;
  color: var(--danger);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.25em;
  text-transform: uppercase;
}
.death-quote {
  max-width: 480px;
  margin-top: 33px;
  font-family: var(--display);
  font-size: 23px;
  line-height: 1.25;
  color: rgba(255, 234, 230, 0.75);
}
.death-quote::before { content: '“'; color: var(--danger); }
.death-quote::after { content: '”'; color: var(--danger); }
.death-stats,
.outro-stats {
  display: flex;
  justify-content: center;
  gap: clamp(24px, 5vw, 65px);
  width: 100%;
  margin-top: 37px;
  padding: 18px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.09);
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
}
.death-stats div,
