/* ==================================================================
   SWALLOW TRANSITION
=================================================================== */

.eat-wipe {
  position: fixed;
  z-index: 100;
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  background: #1b0712;
  transition: opacity 0.25s ease, visibility 0.25s;
}
.eat-wipe.is-active {
  visibility: visible;
  opacity: 1;
}
.eat-wipe::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 80vmax;
  height: 80vmax;
  border-radius: 50%;
  transform: translate(-50%, -50%) scale(0.08);
  background:
    radial-gradient(circle at 50% 45%, #ffc4cf 0 4%, #ff6c93 10%, #dc2e64 28%, #82163d 50%, #2c0818 72%, #0c050a 88%);
  filter: saturate(1.15);
  transition: transform 0.95s cubic-bezier(0.6, 0, 0.3, 1);
}
.eat-wipe.is-active::before {
  transform: translate(-50%, -50%) scale(1.25);
}
.eat-wipe[data-tone='bad']::before {
  background:
    radial-gradient(circle at 50% 45%, #ffd8aa 0 3%, #e46b55 10%, #9c2438 30%, #4d0d21 55%, #1a060e 80%);
}
.wipe-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  border: 1px solid rgba(255, 225, 225, 0.28);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  opacity: 0;
}
.eat-wipe.is-active .wipe-ring {
  animation: wipeRing 1.25s var(--ease-out) forwards;
}
.ring-a { width: 190px; height: 190px; }
.ring-b { width: 380px; height: 380px; animation-delay: 0.1s !important; }
.ring-c { width: 660px; height: 660px; animation-delay: 0.22s !important; }
@keyframes wipeRing {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.35); }
  35% { opacity: 0.5; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.5); }
}
.wipe-content {
  position: relative;
  z-index: 2;
  text-align: center;
  opacity: 0;
  transform: scale(0.9);
}
.eat-wipe.is-active .wipe-content {
  animation: wipeText 0.75s 0.24s var(--ease-out) forwards;
}
@keyframes wipeText {
  to { opacity: 1; transform: scale(1); }
}
.wipe-content p:first-child {
  color: rgba(255, 230, 226, 0.58);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}
.wipe-content h2 {
  margin: 8px 0;
  font-family: var(--display);
  font-size: clamp(80px, 15vw, 190px);
  font-weight: 400;
  line-height: 0.8;
  letter-spacing: -0.05em;
  color: #fff5eb;
  text-shadow: 0 0 70px rgba(255, 195, 170, 0.4);
}
.wipe-content p:last-child {
  color: rgba(255, 232, 226, 0.7);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

/* ==================================================================
   TOAST
=================================================================== */

.toast {
  position: fixed;
  z-index: 120;
  left: 50%;
  bottom: max(22px, env(safe-area-inset-bottom));
  transform: translate(-50%, 16px);
  padding: 10px 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(20, 12, 21, 0.88);
  backdrop-filter: blur(18px);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s var(--ease-out);
}
.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

