input.command:
playwright-cli eval "async () => {
  const { CHARACTERS } = await import('/js/data.js');
  const name = document.querySelector('#date-name').textContent;
  const char = CHARACTERS.find(c => c.name === name);
  const log=[];
  for (let i=0;i<3;i++) {
    const q = document.querySelector('#dialogue-text').textContent;
    const line = char.lines.find(l => l.text === q);
    if (!line) { log.push('no line '+q); break; }
    const good = line.options.find(o=>o.tone==='good').text;
    const btn=[...document.querySelectorAll('.response-btn')].find(b=>b.querySelector('.option-text').textContent===good);
    if (!btn) { log.push('no button'); break; }
    btn.click();
    await new Promise(r=>setTimeout(r,500));
    log.push({q, good, love:document.querySelector('#love-number').textContent, ending:document.querySelector('.date-hint').textContent});
    if (document.querySelector('#love-number').textContent==='100%') break;
    document.dispatchEvent(new KeyboardEvent('keydown',{key:' ',bubbles:true}));
    await new Promise(r=>setTimeout(r,350));
  }
  return log;
}" 2>&1 | head -40

